import fs from "node:fs";
import messages from "../locales/en.mjs";
import { createTranslator } from "../server/i18n.mjs";

const file = new URL("../client.js", import.meta.url);
const source = fs.readFileSync(file, "utf8");
const start = "    /* i18n:generated:start */";
const end = "    /* i18n:generated:end */";
const block = [start,
  "    // Generated by scripts/build-i18n.mjs. Edit locales/en.mjs instead.",
  `    const EN_MESSAGES = Object.freeze(${JSON.stringify(messages, null, 2)});`,
  `    const createTranslator = ${createTranslator.toString()};`,
  "    let localeService = null;",
  "    const activeLanguage = () => localeService?.getSnapshot?.().active || (typeof document !== 'undefined' ? document.documentElement?.lang : '') || 'en';",
  "    const t = createTranslator(EN_MESSAGES, activeLanguage);",
  "    const displayLocale = () => /^zh(?:-|$)/i.test(activeLanguage()) ? 'zh-CN' : 'en';",
  "    function LocaleBoundary({ render }) {",
  "      React.useSyncExternalStore(",
  "        (notify) => localeService?.subscribe?.(notify) || (() => {}),",
  "        () => localeService?.getSnapshot?.().active || 'en',",
  "        () => 'en',",
  "      );",
  "      return render();",
  "    }", end].join("\n");
const a = source.indexOf(start), b = source.indexOf(end, a);
if (a < 0 || b < 0) throw new Error("Client localization markers missing");
const output = source.slice(0, a) + block + source.slice(b + end.length);
if (process.argv.includes("--check")) {
  if (source !== output) throw new Error("Client catalog is stale; run node scripts/build-i18n.mjs");
} else fs.writeFileSync(file, output);
